const lp={i:0,done:COURSES.map(c=>new Set())};
function renderLP(){
  const c=COURSES[lp.i],d=lp.done[lp.i];
  $('#lpTabs').innerHTML=COURSES.map((x,i)=>'<button class="tab" role="tab" type="button" aria-selected="'+(i===lp.i)+'" data-i="'+i+'">'+x.title+'</button>').join('');
  $('#lpTitle').textContent=c.title;
  $('#lpMods').innerHTML=c.modules.map((m,i)=>'<li><button type="button" aria-pressed="'+d.has(i)+'" data-m="'+i+'"><span class="dot">'+(d.has(i)?'✓':i+1)+'</span><span><b style="font-weight:600">'+m[0]+'</b><br><span style="color:var(--ink2);font-size:14px">'+m[1]+'</span></span></button></li>').join('');
  const p=Math.round(d.size/c.modules.length*100);
  $('#lpCount').textContent=d.size+' von '+c.modules.length+' Modulen (Vorschau)';
  $('#ringFg').style.strokeDashoffset=163.4*(1-p/100);$('#ringTx').textContent=p+'%';
}
$('#lpTabs').addEventListener('click',e=>{const b=e.target.closest('.tab');if(b){lp.i=+b.dataset.i;renderLP()}});
$('#lpMods').addEventListener('click',e=>{const b=e.target.closest('button[data-m]');if(!b)return;const s=lp.done[lp.i],m=+b.dataset.m;s.has(m)?s.delete(m):s.add(m);renderLP();if(s.size===COURSES[lp.i].modules.length)toast('Vorschau abgeschlossen. Im echten Kurs folgt dein persönlicher Plan.')});
renderLP();

