function heroGo(){
  const mods=COURSES.reduce((a,c)=>a+c.modules.length,0),docs=COURSES.reduce((a,c)=>a+MAT[c.key].length,0);
  const t={c:COURSES.length,m:mods,u:docs,z:CFG.accessMonths},ch=$('[data-hc="mods"]');
  const els=$$('[data-hs]');
  const set=(el,v)=>{el.textContent=v};
  const fin=()=>{els.forEach(e=>set(e,t[e.dataset.hs]));if(ch)set(ch,mods)};
  if(RM){fin();return}
  const t0=performance.now(),dur=1500;
  const step=now=>{const k=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-k,3);els.forEach(x=>set(x,Math.round(t[x.dataset.hs]*e)));if(ch)set(ch,Math.round(mods*e));if(k<1)requestAnimationFrame(step);else fin()};
  setTimeout(()=>requestAnimationFrame(step),900);
}
if(document.body.classList.contains('pre'))addEventListener('hero-go',heroGo,{once:true});else heroGo();

