async function seedSample(on){
  if(!BE.db||!BE.admin)return;AD.busy=true;
  try{
    if(on){
      const now=Date.now(),D=864e5,n=[['Anna M.',0,[0,1]],['Lea K.',1,[1]],['Sara B.',2,[2,0]],['Nina W.',4,[0]],['Julia R.',6,[1,2]],['Mara T.',9,[0]],['Elena S.',12,[2]],['Tina F.',15,[0,1,2]]];
      let i=0;
      for(const [nm,ago,cs] of n){
        const id='sample-'+(++i),mail='beispiel'+i+'@example.ch',owned=cs.map(k=>COURSES[k].slug);
        const done={};owned.forEach((s,j)=>{done[s]=Math.min(6,(i+j)%6)});
        await BE.db.collection('members').doc(id).set({name:nm,mail,owned,done,total:owned.length*6,ts:now-ago*D,sample:true});
        const its=[];
        for(const [j,s] of owned.entries()){const net=CFG.price[s],g=gross(net);its.push({slug:s,title:bySlug[s].title,net,vat:Math.round((g-net)*100)/100,gross:g,uid:id,name:nm,mail,ts:now-ago*D-j*36e5,status:'Beispiel, keine Zahlung',sample:true})}
        await BE.db.collection('orders').doc(id).set({items:its,sample:true})
      }
      const L=[['Carla P.','Wie läuft der Einstieg bei «She Builds» ab? Brauche ich Vorwissen?','she-builds','neu',0],['Monika H.','Gibt es die Unterlagen auch zum Ausdrucken?','woman-first','neu',1],['Ines L.','Danke für die schnelle Antwort!','', 'erledigt',5]];
      for(const [k,x] of L.entries())await BE.db.collection('leads').doc('sample-l'+k).set({sample:true,items:[{name:x[0],mail:'beispiel-anfrage'+k+'@example.ch',msg:x[1],course:x[2],status:x[3],ts:now-x[4]*D,sample:true}]});
    }else{
      for(const c of ['orders','members','leads']){const sn=await BE.db.collection(c).get();for(const d of sn.docs)if((d.data()||{}).sample===true)await BE.db.collection(c).doc(d.id).delete()}
    }
    toast(on?'Beispieldaten eingespielt':'Beispieldaten entfernt');
  }catch(e){toast('Das hat nicht geklappt ('+(e&&e.code||'Fehler')+').')}
  AD.busy=false;if(isAdminRoute())renderAdmin(decodeURIComponent(location.hash.slice(1)),true);
}
crs.addEventListener('click',async e=>{
  const b=e.target.closest('[data-adm]');if(!b)return;
  const a=b.dataset.adm;
  if(!BE.db||!BE.admin)return;
  if(a==='seed')return seedSample(true);
  if(a==='unseed')return seedSample(false);
  if(a==='del'){
    if(b.dataset.armed!=='1'){b.dataset.armed='1';b.textContent='Wirklich löschen?';setTimeout(()=>{if(b.isConnected){b.dataset.armed='0';b.textContent='Löschen'}},3500);return}
    try{const c=b.dataset.c,[did,ix]=b.dataset.id.split('#'),ref=BE.db.collection(c).doc(did);
      if(c==='members')await ref.delete();else{const r=await ref.get(),it=((r.exists&&r.data().items)||[]).filter((_,k)=>k!==+ix);if(it.length)await ref.update({items:it});else await ref.delete()}
      toast('Eintrag gelöscht')}catch(er){toast('Löschen nicht möglich.')}return}
  if(a==='acc'){const x=AD.leads.find(l=>l.id===b.dataset.id);if(!x)return;try{const ref=BE.db.collection('leads').doc(x.doc),r=await ref.get(),it=((r.exists&&r.data().items)||[]).slice();it[x.idx]=Object.assign({},it[x.idx],{status:b.dataset.v,decidedTs:Date.now()});await ref.update({items:it});toast(b.dataset.v==='freigegeben'?'Zugang freigegeben':'Antrag abgelehnt')}catch(er){toast('Das hat nicht geklappt.')}return}
  if(a==='tog'){const x=AD.leads.find(l=>l.id===b.dataset.id);if(!x)return;try{const ref=BE.db.collection('leads').doc(x.doc),r=await ref.get(),it=((r.exists&&r.data().items)||[]).slice();it[x.idx]=Object.assign({},it[x.idx],{status:x.status==='erledigt'?'neu':'erledigt'});await ref.update({items:it})}catch(er){toast('Änderung nicht möglich.')}return}
  if(a==='csv'){
    const q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"',rows=[['Datum','Name','E-Mail','Masterclass','Netto','MwSt','Brutto','Status']].concat(orderRows().map(x=>[new Date(x.ts).toISOString(),x.name,x.mail,x.title,x.net,x.vat,x.gross,x.status]));
    const csv='﻿'+rows.map(r=>r.map(q).join(';')).join('\r\n');
    if(!BE.dl){toast('Export ist in dieser Ansicht nicht verfügbar.');return}
    try{await BE.dl.save({filename:'bestellungen-unternehmerfrauen.csv',data:csv});toast('CSV gespeichert')}catch(er){if(!(er&&er.code==='declined'))toast('Export nicht möglich.')}
  }
});

/* ---------- Lernwelt: Kursplayer, Level, Erfolge, Notizen ---------- */
const LEVELS=[[0,'Starterin'],[30,'Entdeckerin'],[80,'Gestalterin'],[150,'Macherin'],[250,'Vorbild']];
const nk=(s,i)=>s+'|'+i;
function stats(){
  const notes=Object.values(S.notes||{}).filter(t=>t&&t.trim()).length,steps=Object.values(S.steps||{}).filter(Boolean).length;
  const mods=COURSES.reduce((a,c)=>a+(owns(c.slug)?doneOf(c.slug).length:0),0);
  const pts=mods*10+notes*2+steps*5;
  let li=0;LEVELS.forEach((l,i)=>{if(pts>=l[0])li=i});
  const nxt=LEVELS[li+1],base=LEVELS[li][0];
  return {notes,steps,mods,pts,li,name:LEVELS[li][1],nxt,pct:nxt?Math.round((pts-base)/(nxt[0]-base)*100):100,streak:streakDays(),courseDone:COURSES.some(c=>owns(c.slug)&&doneOf(c.slug).length===c.modules.length)};
}
function streakDays(){
  const days=new Set(S.log.map(l=>{const d=new Date(l.t);return new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime()}));
  const now=new Date(),t0=new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime();
  let n=0,t=days.has(t0)?t0:t0-864e5;
  while(days.has(t)){n++;t-=864e5}
  return n;
}
const BADGES=[
 ['start','Erster Schritt','Dein erstes Modul abgeschlossen',s=>s.mods>=1],
 ['streak','Dranbleiberin','An 3 Tagen in Folge gelernt',s=>s.streak>=3],
 ['notes','Gedanken festgehalten','5 Notizen geschrieben',s=>s.notes>=5],
 ['steps','Macherin','3 Umsetzungsschritte erledigt',s=>s.steps>=3],
 ['course','Kurs geschafft','Eine Masterclass vollständig abgeschlossen',s=>s.courseDone],
 ['all','Lernwelt komplett','Alle drei Masterclasses freigeschaltet',s=>COURSES.every(c=>owns(c.slug))]
];
const nextMod=()=>{for(const c of COURSES){if(!owns(c.slug))continue;const i=c.modules.findIndex((m,k)=>!doneOf(c.slug).includes(k));if(i>-1)return {c,i}}return null};
function pathHTML(){
  return COURSES.map(c=>{
    const has=owns(c.slug),d=has?doneOf(c.slug):[],nx=has?c.modules.findIndex((m,k)=>!d.includes(k)):-1;
    return `<div class="lwrow${has?'':' locked'}"><div class="lwt"><span class="nr">MASTERCLASS ${c.nr}</span><b>${c.title}</b></div><ol class="lwpath" aria-label="Lernpfad ${c.title}">${c.modules.map((m,i)=>{
      const st=!has?'lock':d.includes(i)?'done':i===nx?'next':'todo';
      const href=has?`#lernen-${c.slug}-${i}`:`#kasse-${c.slug}`;
      return `<li class="${st}"><a href="${href}" aria-label="${has?'Modul '+(i+1)+': '+E(m[0])+(st==='done'?', erledigt':st==='next'?', als Nächstes':''):'Freischalten'}"><span class="nd">${st==='done'?'✓':st==='lock'?'🔒':i+1}</span><span class="nl">${E(m[0])}</span></a></li>`}).join('')}</ol></div>`}).join('');
}
function worldTop(){
  const st=stats(),nx=nextMod(),p=profile();
  const hello=p.name?'Hallo '+E(p.name)+'.':'Willkommen in deiner Lernwelt.';
  const hero=`<div class="lwhero"><div><p class="eyebrow" style="color:#D1AE82">Deine Lernwelt</p><h1>${hello}</h1>${nx?`<p class="lwsub">Heute dran: <b>${nx.c.title}</b>, Modul ${nx.i+1}: ${E(nx.c.modules[nx.i][0])}. Rechne mit etwa ${CFG.minPerModule} Minuten.</p><div class="cta-row" style="margin:0"><a class="btn" href="#lernen-${nx.c.slug}-${nx.i}">Jetzt lernen ${ARROW}</a></div>`:S.owned.length?`<p class="lwsub">Du hast alle Module deiner Masterclasses abgeschlossen. Stark!</p>`:`<p class="lwsub">Schalte deine erste Masterclass frei, um zu starten. Hier siehst du dann deinen Lernpfad, deine Erfolge und deine Notizen.</p><div class="cta-row" style="margin:0"><a class="btn" href="#masterclasses">Masterclasses ansehen ${ARROW}</a></div>`}</div>
  <div class="lwlvl"><div class="lvn">Level ${st.li+1}</div><b>${st.name}</b><div class="pbar" role="progressbar" aria-label="Fortschritt zum nächsten Level" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${st.pct}"><i style="width:${st.pct}%"></i></div><small>${st.pts} Punkte${st.nxt?`, noch ${st.nxt[0]-st.pts} bis «${st.nxt[1]}»`:''}</small><div class="lwmini"><span><b>${st.streak}</b> ${st.streak===1?'Tag':'Tage'} in Folge</span><span><b>${st.mods}</b> Module</span><span><b>${st.notes}</b> Notizen</span></div></div></div>`;
  const dk=dayKey(),imp=`<div class="panel impulse" style="margin-bottom:16px"><p class="eyebrow">Dein Tagesimpuls</p><p class="q">${E(impulseOf(dk))}</p><label for="impNote" class="vh">Deine Antwort</label><textarea id="impNote" class="note" rows="3" data-act="note" data-n="impuls|${dk}" placeholder="Schreib dir ein, zwei Sätze auf. Das genügt.">${E((S.notes||{})['impuls|'+dk]||'')}</textarea><small id="noteSt" style="color:var(--ink2)" aria-live="polite"></small></div>`;
  const earned=BADGES.filter(b=>b[3](st));
  const sec=`<div class="panel" style="margin-bottom:16px"><h2>Dein Lernpfad</h2><p style="color:var(--ink2);margin:0">Jeder Punkt ist ein Modul. Tippe auf einen Punkt, um direkt dorthin zu springen.</p>${pathHTML()}</div>
  <div class="panel" style="margin-bottom:16px"><div class="dh" style="margin:0"><h2>Erfolge</h2><a class="link" href="#dashboard-erfolge">Alle ansehen ${ARROW}</a></div><div class="bgrow">${earned.length?earned.slice(0,4).map(b=>`<span class="bgd on"><i>★</i>${b[1]}</span>`).join(''):'<span style="color:var(--ink2)">Dein erster Erfolg wartet auf dich: schliesse ein Modul ab.</span>'}</div></div>
  <div class="dg eq" style="margin-bottom:16px"><div class="panel appmini"><span class="ph" style="justify-self:start">Bald</span><h2>Die App kommt</h2><p style="color:var(--ink2);margin:0">Deine Lernwelt bald auch im App Store und bei Google Play. Trag dich auf die Warteliste ein.</p><div><a class="btn ghost sm" href="#app">Zur App-Warteliste</a></div></div><div class="panel appmini"><h2>Bring eine Freundin mit</h2><p style="color:var(--ink2);margin:0">Kennst du eine Frau, die gerade ihren nächsten Schritt sucht? Teile unternehmerfrauen.ch mit ihr.</p><div><button class="btn ghost sm" type="button" data-act="sharecopy" data-k="share">Link kopieren</button></div></div></div>`;
  return (S.sample?'<p class="status" style="margin-bottom:18px">Beispieldaten: Alle Zahlen hier sind Demo-Werte, keine echten Lernstände.</p>':'')+hero+imp+sec+`<div style="margin-bottom:18px">${sampleBtn()}</div>`;
}
/* Kursplayer */
function playerParse(h){const m=/^lernen-(.+?)(?:-(\d+))?$/.exec(h);if(!m)return null;let slug=m[1],i=m[2];if(!bySlug[slug]){const mm=/^(.+)-(\d+)$/.exec(h.slice(7));if(mm&&bySlug[mm[1]]){slug=mm[1];i=mm[2]}else return null}return {c:bySlug[slug],i:Math.min(Math.max(+i||0,0),bySlug[slug].modules.length-1)}}
const REFL=t=>[`Was bedeutet «${t}» konkret für deinen Alltag?`,'Welchen kleinen Schritt kannst du diese Woche dazu gehen?','Was hat dich bisher davon abgehalten, und was brauchst du, um es zu ändern?'];
function renderPlayer(h){
  const P=playerParse(h);
  if(!P){crs.innerHTML=ashellNone();return}
  const {c,i}=P,m=c.modules[i];
  if(!owns(c.slug)){crs.innerHTML=`<section class="chero" style="padding-bottom:clamp(56px,8vw,96px)"><div class="wrap" style="max-width:820px"><a class="crumb" href="#${c.slug}">${ARROW} Zur Masterclass</a><p class="eyebrow" style="margin-top:12px">${c.title}</p><h1 style="font-size:clamp(34px,6vw,64px);margin:12px 0 18px;font-weight:500">Diese Masterclass ist noch nicht freigeschaltet.</h1><p class="lead">Schalte «${c.title}» frei, um die Module, Übungen und Unterlagen zu nutzen.</p><div class="cta-row"><a class="btn" href="#kasse-${c.slug}">Jetzt freischalten ${ARROW}</a></div></div></section>`;return}
  const d=doneOf(c.slug),done=d.includes(i),k=nk(c.slug,i),pct=Math.round(d.length/c.modules.length*100);
  const prev=i>0?`#lernen-${c.slug}-${i-1}`:null,next=i<c.modules.length-1?`#lernen-${c.slug}-${i+1}`:null;
  crs.innerHTML=`<div class="wrap lwp"><aside class="lwside" aria-label="Module von ${c.title}"><a class="crumb" href="#dashboard">${ARROW} Lernwelt</a><b class="lwct">${c.title}</b><div class="pbar" role="progressbar" aria-label="Kursfortschritt" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div><small style="color:var(--ink2)">${d.length} von ${c.modules.length} Modulen</small><ol class="lwmods">${c.modules.map((x,j)=>`<li><a href="#lernen-${c.slug}-${j}"${j===i?' aria-current="page"':''}><span class="dot">${d.includes(j)?'✓':j+1}</span><span>${E(x[0])}</span></a></li>`).join('')}</ol></aside>
  <article class="lwmain"><p class="eyebrow">Modul ${i+1} von ${c.modules.length} · ca. ${CFG.minPerModule} Min.</p><h1>${E(m[0])}</h1><p class="lead">${E(m[1])}</p>
  <div class="vidph" role="img" aria-label="Platzhalter für das Lernvideo"><span class="ph">Video folgt</span><p>Hier erscheint das Lernvideo zu diesem Modul, sobald es produziert ist.</p></div>
  <section class="panel" style="margin-top:18px"><h2>Reflexion</h2><ol class="refl">${REFL(m[0]).map(q=>`<li>${E(q)}</li>`).join('')}</ol><label for="note" style="font-weight:600">Deine Notizen</label><textarea id="note" class="note" data-act="note" data-n="${k}" rows="6" placeholder="Schreib hier auf, was dir in den Sinn kommt. Nur du siehst das.">${E((S.notes||{})[k]||'')}</textarea><small id="noteSt" style="color:var(--ink2)" aria-live="polite"></small></section>
  <section class="panel" style="margin-top:16px"><h2>Dein Umsetzungsschritt</h2><label class="chk"><input type="checkbox" data-act="step" data-n="${k}"${(S.steps||{})[k]?' checked':''}><span>Ich habe mir für diese Woche einen konkreten Schritt vorgenommen und erledigt.</span></label></section>
  <div class="lwnav">${prev?`<a class="btn ghost" href="${prev}">Zurück</a>`:'<span></span>'}<button class="btn${done?' ghost':''}" type="button" data-act="pdone" data-s="${c.slug}" data-i="${i}" data-k="pdone">${done?'Als offen markieren':'Modul abschliessen'}</button>${next?`<a class="btn ghost" href="${next}">Weiter ${ARROW}</a>`:`<a class="btn ghost" href="#dashboard-kurse">Zu meinen Kursen</a>`}</div></article></div>`;
}
const ashellNone=()=>`<section class="chero"><div class="wrap"><a class="crumb" href="#dashboard">${ARROW} Lernwelt</a><h1 style="font-size:clamp(34px,6vw,64px)">Modul nicht gefunden.</h1></div></section>`;
function vNotes(){
  const rows=[];COURSES.forEach(c=>c.modules.forEach((m,i)=>{const t=(S.notes||{})[nk(c.slug,i)];if(t&&t.trim())rows.push({c,i,m,t})}));
  Object.keys(S.notes||{}).filter(k=>k.startsWith('impuls|')&&(S.notes[k]||'').trim()).sort().reverse().forEach(k=>{const dk=k.slice(7);rows.push({imp:dk,t:S.notes[k]})});
  return dhead('Meine Notizen',sampleBtn())+`<p style="color:var(--ink2);max-width:60ch">Alle deine Reflexionen an einem Ort. Sie sind nur für dich sichtbar.</p><div style="display:grid;gap:14px">${rows.map(r=>r.imp?`<div class="panel"><span class="nr">Tagesimpuls · ${dDE(new Date(r.imp+'T12:00:00'))}</span><h2>${E(impulseOf(r.imp))}</h2><p style="white-space:pre-wrap;margin:0">${E(r.t)}</p></div>`:`<div class="panel"><span class="nr">${r.c.title} · Modul ${r.i+1}</span><h2>${E(r.m[0])}</h2><p style="white-space:pre-wrap;margin:0">${E(r.t)}</p><div><a class="link" href="#lernen-${r.c.slug}-${r.i}">Bearbeiten ${ARROW}</a></div></div>`).join('')||`<div class="panel"><p style="margin:0;color:var(--ink2)">Noch keine Notizen. Du schreibst sie im Kursplayer bei jedem Modul.</p></div>`}</div>`;
}
function vBadges(){
  const st=stats();
  return dhead('Erfolge',sampleBtn())+`<div class="lwlvl wide"><div class="lvn">Level ${st.li+1}</div><b>${st.name}</b><div class="pbar" role="progressbar" aria-label="Fortschritt zum nächsten Level" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${st.pct}"><i style="width:${st.pct}%"></i></div><small>${st.pts} Punkte: 10 je Modul, 5 je Umsetzungsschritt, 2 je Notiz</small></div><div class="bgrid" style="margin-top:16px">${BADGES.map(b=>{const on=b[3](st);return `<div class="bgc${on?' on':''}"><i aria-hidden="true">${on?'★':'☆'}</i><b>${b[1]}</b><span>${b[2]}</span><small>${on?'Erreicht':'Noch offen'}</small></div>`}).join('')}</div>`;
}
/* Events */
crs.addEventListener('click',e=>{
  const sh=e.target.closest('[data-act="sharecopy"]');
  if(sh){const t='Ich lerne gerade bei unternehmerfrauen.ch, Masterclasses von Frauen für Frauen: https://unternehmerfrauen.ch';(navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).then(()=>toast('Link kopiert')).catch(()=>toast('Kopieren nicht möglich. Der Link: unternehmerfrauen.ch'));return}
  const b=e.target.closest('[data-act="pdone"]');if(!b)return;
  const s=b.dataset.s,i=+b.dataset.i,d=doneOf(s),lb=stats().li;
  if(d.includes(i)){S.done[s]=d.filter(x=>x!==i);const li=S.log.map(l=>l.slug===s&&l.i===i).lastIndexOf(true);if(li>-1)S.log.splice(li,1)}
  else{d.push(i);S.log.push({t:Date.now(),slug:s,i});const c=bySlug[s];toast(d.length===c.modules.length?'Masterclass abgeschlossen! Deine Teilnahmebestätigung wartet unter «Meine Kurse».':'Modul abgeschlossen: +10 Punkte')}
  save();{const sa=stats();if(sa.li>lb){toast('Level-Aufstieg: du bist jetzt «'+sa.name+'»!');celebrate()}else if(doneOf(s).length===bySlug[s].modules.length)celebrate()}
  renderPlayer(decodeURIComponent(location.hash.slice(1)));const el=crs.querySelector('[data-k="pdone"]');el&&el.focus({preventScroll:true});
});
let noteT=null;
crs.addEventListener('input',e=>{
  const t=e.target.closest('[data-act="note"]');if(!t)return;
  (S.notes=S.notes||{})[t.dataset.n]=t.value;clearTimeout(noteT);
  noteT=setTimeout(()=>{save();const st=$('#noteSt',crs);if(st)st.textContent='Gespeichert'},500);
  const st=$('#noteSt',crs);if(st)st.textContent='';
});
crs.addEventListener('change',e=>{
  const t=e.target.closest('[data-act="step"]');if(!t)return;
  const lb=stats().li;(S.steps=S.steps||{})[t.dataset.n]=t.checked;save();{const sa=stats();if(sa.li>lb){celebrate()}}toast(t.checked?'Umsetzungsschritt erledigt: +5 Punkte':'Umsetzungsschritt zurückgesetzt');
});

