/* ---------- Login & Zugangsantrag (Freigabe intern) ---------- */
const AK='uf-auth-v1';
let AU={};try{AU=JSON.parse(localStorage.getItem(AK))||{}}catch(e){}
const auSave=()=>{try{localStorage.setItem(AK,JSON.stringify(AU))}catch(e){}};
const MAILRE=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const roleOf=h=>(h==='admin'||h.startsWith('admin-')||h==='login-admin')?'admin':'member';
const authed=role=>AU.status==='approved'&&(role==='member'||AU.role==='admin');
const needsAuth=h=>h==='dashboard'||h.startsWith('dashboard-')||h.startsWith('lernen-')||h==='admin'||h.startsWith('admin-');
const pendAcc=()=>AD.leads.filter(x=>x.kind==='access'&&x.status==='neu').length;
let NEXT=null;
async function api(path,body){const r=await fetch(CFG.apiBase+path,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(body)});let j={};try{j=await r.json()}catch(e){}return{ok:r.ok,j}}
function goAfter(role){const t=NEXT&&roleOf(NEXT)===role&&needsAuth(NEXT)?NEXT:(role==='admin'?'admin':'dashboard');NEXT=null;if(decodeURIComponent(location.hash.slice(1))===t)route();else location.hash='#'+t}
function authNote(role){
  if(AU.role!==role&&!(role==='member'&&AU.role==='admin'))return '';
  if(AU.status==='pending')return `<div class="lg-note ok" role="status"><p><b>Dein Antrag ist eingegangen.</b> Wir prüfen ihn intern. Dein Login wird erst nach unserer Freigabe aktiv${LIVE?'. Du erhältst Bescheid per E-Mail.':'. In der Demo wird keine E-Mail versendet, die Freigabe erfolgt im Admin-Bereich unter «Zugangsanträge».'}</p></div>`;
  if(AU.status==='rejected')return `<div class="lg-note" role="status"><p><b>Dein Antrag wurde nicht freigegeben.</b> Wenn du Fragen hast, schreib uns an ${CFG.mail}.</p></div>`;
  return '';
}
function renderLogin(role){
  const adm=role==='admin',area=adm?'Admin-Bereich':'Mein Bereich';
  const head=`<section class="chero" style="padding-bottom:clamp(56px,8vw,96px)"><div class="wrap"><a class="crumb" href="#">${ARROW} Zur Startseite</a><p class="eyebrow" style="margin-top:12px">${area}</p><h1 style="font-size:clamp(36px,6vw,72px);margin:12px 0 18px;font-weight:500">Anmelden</h1>`;
  const foot=`<p class="small-note" style="margin-top:26px">${adm?'<a href="#login">Zum Login für Mein Bereich</a>':'<a href="#login-admin">Zum Admin-Login</a>'}</p></div></section>`;
  if(authed(role)){crs.innerHTML=head+`<div class="lg-note ok"><p><b>Du bist angemeldet.</b></p></div><div class="cta-row"><a class="btn" href="#${adm?'admin':'dashboard'}">Zum ${area} ${ARROW}</a><button class="btn ghost" type="button" data-act="logout">Abmelden</button></div>`+foot;return}
  if(LIVE&&!CFG.apiBase){crs.innerHTML=head+`<p class="lead" style="max-width:62ch">Der Login für ${adm?'den Admin-Bereich':'Mein Bereich'} startet mit der Eröffnung der Plattform. Neue Zugänge werden erst nach interner Freigabe aktiviert.</p><div class="lg-note"><p>Möchtest du frühzeitig Zugang beantragen? Schreib uns an <b>${CFG.mail}</b>.</p></div>`+foot;return}
  crs.innerHTML=head+`<p class="lead" style="max-width:62ch">${adm?'Nur für das Team. Neue Admin-Zugänge gibt die Inhaberin intern frei.':'Melde dich mit deinem freigegebenen Zugang an. Neu hier? Beantrage deinen Zugang, wir prüfen jeden Antrag intern, bevor das Login aktiv wird.'}</p>${authNote(role)}
  <div class="lg-grid"><form class="card" id="lgForm" data-role="${role}" novalidate style="display:grid;gap:14px"><h3>Login</h3><div class="fld"><label for="lgMail">E-Mail</label><input id="lgMail" type="email" autocomplete="username" value="${E(AU.mail||'')}"></div>${LIVE?'<div class="fld"><label for="lgPw">Passwort</label><input id="lgPw" type="password" autocomplete="current-password"></div>':'<p class="small-note" style="margin:0">In der Demo gibt es kein Passwort. Die Freigabe wird anhand deines Antrags geprüft.</p>'}<div class="lg-err" id="lgErr" role="alert"></div><button class="btn" type="submit">Anmelden ${ARROW}</button></form>
  <form class="card" id="rqForm" data-role="${role}" novalidate style="display:grid;gap:14px"><h3>Zugang beantragen</h3><div class="fld"><label for="rqName">Name</label><input id="rqName" autocomplete="name" value="${E(AU.name||'')}"></div><div class="fld"><label for="rqMail">E-Mail</label><input id="rqMail" type="email" autocomplete="email" value="${E(AU.mail||'')}"></div><div class="fld"><label for="rqMsg">${adm?'Wofür brauchst du Admin-Zugang?':'Nachricht (optional)'}</label><textarea id="rqMsg" rows="3" maxlength="600"></textarea></div><label class="chk"><input type="checkbox" id="rqOk"><span>Ich habe die <a href="#datenschutz">Datenschutzhinweise</a> gelesen.</span></label><div class="lg-err" id="rqErr" role="alert"></div><button class="btn" type="submit">Antrag senden ${ARROW}</button></form></div>
  ${LIVE?'':`<div class="lg-note" style="margin-top:22px"><p><b>Nur für die Vorschau:</b> Du kannst die Freigabe überspringen und den Bereich direkt ansehen.</p><p style="margin-top:12px"><button class="btn ghost sm" type="button" data-act="demoin" data-role="${role}">Vorschau ohne Login öffnen</button></p></div>`}`+foot;
}
crs.addEventListener('click',e=>{
  const b=e.target.closest('[data-act="logout"],[data-act="demoin"]');if(!b)return;
  if(b.dataset.act==='logout'){const was=AU.role;if(LIVE&&CFG.apiBase)fetch(CFG.apiBase+'/auth/logout',{method:'POST',credentials:'include'}).catch(()=>{});AU={};auSave();location.hash=was==='admin'?'#login-admin':'#login';if(!location.hash)route();return}
  AU={status:'approved',role:b.dataset.role,demo:true,mail:AU.mail||'',name:AU.name||''};auSave();goAfter(b.dataset.role);
});
crs.addEventListener('submit',async e=>{
  const f=e.target;
  if(f.id==='lgForm'){
    e.preventDefault();const role=f.dataset.role,er=$('#lgErr'),mail=$('#lgMail').value.trim().toLowerCase();er.textContent='';
    if(!MAILRE.test(mail)){er.textContent='Bitte gib deine E-Mail-Adresse an.';return}
    if(LIVE){
      const pw=$('#lgPw').value;if(!pw){er.textContent='Bitte gib dein Passwort an.';return}
      try{const r=await api('/auth/login',{mail,password:pw,role});const st=r.j&&r.j.status;
        if(r.ok&&st==='approved'){AU={status:'approved',role:r.j.role||role,mail,name:r.j.name||''};auSave();goAfter(role);return}
        if(st==='pending'||st==='rejected'){AU={status:st,role,mail};auSave();renderLogin(role);return}
        er.textContent='E-Mail oder Passwort stimmt nicht, oder dein Zugang ist noch nicht freigegeben.'}catch(x){er.textContent='Der Login ist gerade nicht erreichbar. Versuche es später noch einmal.'}
      return}
    if(!BE.db||!BE.id){er.textContent='Die Prüfung ist nur in der Claude-Vorschau möglich. Nutze «Vorschau ohne Login öffnen».';return}
    try{const r=await BE.db.collection('leads').doc(BE.id).get(),it=((r.exists&&r.data().items)||[]).filter(x=>x.kind==='access'&&(x.role||'member')===role&&String(x.mail).toLowerCase()===mail);
      const x=it[it.length-1];
      if(!x){er.textContent='Zu dieser E-Mail liegt kein Antrag vor. Beantrage rechts deinen Zugang.';return}
      if(x.status==='freigegeben'){AU={status:'approved',role,mail,name:x.name||''};auSave();goAfter(role);return}
      AU={status:x.status==='abgelehnt'?'rejected':'pending',role,mail,name:x.name||''};auSave();renderLogin(role)}catch(x){er.textContent='Das hat nicht geklappt. Bitte versuche es noch einmal.'}
    return}
  if(f.id==='rqForm'){
    e.preventDefault();const role=f.dataset.role,er=$('#rqErr'),name=$('#rqName').value.trim(),mail=$('#rqMail').value.trim(),msg=$('#rqMsg').value.trim();er.textContent='';
    if(!name){er.textContent='Bitte gib deinen Namen an.';return}
    if(!MAILRE.test(mail)){er.textContent='Bitte gib eine gültige E-Mail-Adresse an.';return}
    if(!$('#rqOk').checked){er.textContent='Bitte bestätige die Datenschutzhinweise.';return}
    let ok=false;
    if(LIVE){if(CFG.apiBase){try{ok=(await api('/auth/request',{name,mail,message:msg,role})).ok}catch(x){}}else ok=await recordLead({name,mail,role,kind:'access',msg:'Zugangsantrag '+(role==='admin'?'Admin':'Mein Bereich')+(msg?': '+msg:'')})}
    else ok=await recordLead({name,mail,role,kind:'access',msg:'Zugangsantrag '+(role==='admin'?'Admin':'Mein Bereich')+(msg?': '+msg:'')});
    if(!ok){er.textContent=LIVE?'Der Antrag konnte nicht gesendet werden. Schreib uns bitte an '+CFG.mail+'.':'Der Antrag konnte in dieser Ansicht nicht gespeichert werden. Nutze «Vorschau ohne Login öffnen».';return}
    AU={status:'pending',role,mail,name,ts:Date.now()};auSave();track('access_request',{role});renderLogin(role);return}
  if(f.id==='ckForm'){
    e.preventDefault();const er=$('#ckErr'),n=$('#ckName').value.trim(),m=$('#ckMail').value.trim();er.textContent='';
    if(!n||!MAILRE.test(m)){er.textContent='Bitte gib deinen Vornamen und eine gültige E-Mail-Adresse an.';return}
    if(!$('#ckOk').checked){er.textContent='Bitte bestätige die Datenschutzhinweise.';return}
    const ok=await recordLead({name:n,mail:m,course:f.dataset.s,kind:'preorder',msg:'Vorregistrierung '+bySlug[f.dataset.s].title});
    const st=$('#ckSt');st.hidden=false;st.textContent=liveMsg(ok);track('preorder',{slug:f.dataset.s,sent:ok});
  }
});
function vAAccess(){
  const r=AD.leads.filter(x=>x.kind==='access').sort((a,b)=>b.ts-a.ts);
  const lab={freigegeben:'Freigegeben',abgelehnt:'Abgelehnt'};
  return ahead('Zugangsanträge')+`<p style="color:var(--ink2);max-width:62ch;margin:0 0 18px">Zugänge werden erst nach interner Freigabe aktiv. Prüfe jeden Antrag und gib ihn frei oder lehne ihn ab. Admin-Zugänge gibt nur die Inhaberin frei.</p>`+(r.length?`<div class="panel"><div class="tbl"><table><thead><tr><th>Datum</th><th>Name</th><th>E-Mail</th><th>Bereich</th><th>Status</th><th>Aktion</th></tr></thead><tbody>${r.map(x=>`<tr><td>${fmtD(x.ts)}</td><td>${E(x.name)}</td><td>${E(x.mail)}</td><td>${x.role==='admin'?'Admin':'Mein Bereich'}</td><td><span class="bdg">${lab[x.status]||'In Prüfung'}</span></td><td><button class="btn sm" type="button" data-adm="acc" data-v="freigegeben" data-id="${E(x.id)}">Freigeben</button> <button class="btn ghost sm" type="button" data-adm="acc" data-v="abgelehnt" data-id="${E(x.id)}">Ablehnen</button></td></tr>`).join('')}</tbody></table></div></div>`:'<div class="panel"><p style="margin:0">Noch keine Anträge.</p></div>');
}
